@contextlib.contextmanager
def active_status_timer(initial_msg: str):
    """
    Rich status context manager with real-time live elapsed timer.
    Displays elapsed seconds/minutes in the spinner AND prints an explicit heartbeat every 15s.
    """
    with console.status(initial_msg) as status:
        stop_event = threading.Event()
        start_time = time.time()

        def ticker():
            last_heartbeat = 0
            while not stop_event.is_set():
                time.sleep(1)
                elapsed = int(time.time() - start_time)
                m, s = divmod(elapsed, 60)
                time_str = f"{m} นาที {s:02d} วินาที" if m > 0 else f"{s} วินาที"

                # 1. Update spinner text live every second
                try:
                    status.update(f"{initial_msg} [bold yellow]({time_str})[/bold yellow] [dim]| รันต่อเนื่องไม่จำกัดเวลา[/dim]")
                except Exception:
                    pass

                # 2. Print an explicit heartbeat line every 15 seconds so progress is 100% visible on screen
                if elapsed >= last_heartbeat + 15:
                    last_heartbeat = elapsed
                    try:
                        console.print(f"    [dim]--> กำลังเขียนโค้ดต่อเนื่อง... (ผ่านไปแล้ว [bold yellow]{time_str}[/bold yellow] | ไม่จำกัดเวลา)[/dim]")
                    except Exception:
                        pass

        t = threading.Thread(target=ticker, daemon=True)
        t.start()
        try:
            yield status
        finally:
            stop_event.set()


