@dataclass
class BlueprintTopic:
    """Represents a single modular topic in the engineering blueprint."""
    topic_id: int
    title: str
    description: str
    target_files: List[str]
    requirements: List[str]
    acceptance_criteria: List[str]
    test_commands: List[str] = field(default_factory=list)
    status: str = "PENDING"


@dataclass
class QAEvaluation:
    """Evaluation result generated by Agent 1 (QA Tester)."""
    passed: bool
    feedback_points: List[str] = field(default_factory=list)
    terminal_errors: List[str] = field(default_factory=list)
    terminal_stdout: str = ""
    summary: str = ""


@dataclass
class WorkerOutput:
    """Result and artifacts produced by Agent 2 (Frontend Coder)."""
    files_written: Dict[str, str] = field(default_factory=dict)
    notes: str = ""
    raw_response: str = ""


@dataclass
class TopicRunReport:
    """Historical record for a topic execution."""
    topic_id: int
    title: str
    status: str  # APPROVED | FAILED | MAX_ITERATIONS_REACHED
    iterations_used: int
    files_created: List[str]
    final_feedback: str


