class BaseLLMProvider(ABC):
    """Abstract interface for LLM backends."""
    @abstractmethod
    def generate(self, system_prompt: str, user_prompt: str) -> str:
        pass


class GoogleGenAIProvider(BaseLLMProvider):
    """Provider for Google Gemini models via google-genai SDK."""
    def __init__(self, model_name: str = "gemini-2.5-flash", api_key: Optional[str] = None):
        self.model_name = model_name
        self.api_key = api_key or os.getenv("GEMINI_API_KEY")
        if not self.api_key:
            raise ValueError("GEMINI_API_KEY environment variable or argument is required.")
        from google import genai
        from google.genai import types
        self.client = genai.Client(api_key=self.api_key)
        self.types = types

    def generate(self, system_prompt: str, user_prompt: str) -> str:
        config = self.types.GenerateContentConfig(
            system_instruction=system_prompt,
            temperature=0.2,
        )
        response = self.client.models.generate_content(
            model=self.model_name,
            contents=user_prompt,
            config=config,
        )
        return response.text or ""


class OpenAIProvider(BaseLLMProvider):
    """Provider for OpenAI models via openai SDK."""
    def __init__(self, model_name: str = "gpt-4o", api_key: Optional[str] = None):
        self.model_name = model_name
        self.api_key = api_key or os.getenv("OPENAI_API_KEY")
        if not self.api_key:
            raise ValueError("OPENAI_API_KEY environment variable or argument is required.")
        from openai import OpenAI
        self.client = OpenAI(api_key=self.api_key)

    def generate(self, system_prompt: str, user_prompt: str) -> str:
        response = self.client.chat.completions.create(
            model=self.model_name,
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt},
            ],
            temperature=0.2,
        )
        return response.choices[0].message.content or ""


class AnthropicProvider(BaseLLMProvider):
    """Provider for Anthropic Claude models via anthropic SDK."""
    def __init__(self, model_name: str = "claude-3-5-sonnet-20241022", api_key: Optional[str] = None):
        self.model_name = model_name
        self.api_key = api_key or os.getenv("ANTHROPIC_API_KEY")
        if not self.api_key:
            raise ValueError("ANTHROPIC_API_KEY environment variable or argument is required.")
        from anthropic import Anthropic
        self.client = Anthropic(api_key=self.api_key)

    def generate(self, system_prompt: str, user_prompt: str) -> str:
        response = self.client.messages.create(
            model=self.model_name,
            system=system_prompt,
            messages=[{"role": "user", "content": user_prompt}],
            max_tokens=4096,
            temperature=0.2,
        )
        return response.content[0].text or ""


