from antigravity_accounts import AntigravityCredentialManager

class AntigravityCLIProvider(BaseLLMProvider):
    """
    Provider that invokes Antigravity CLI ('agy') locally non-interactively via --print.
    Uses logged-in Google Antigravity accounts without any API keys.
    Supports dynamic account switching between Master and Worker profiles.
    Default execution timeout is 180s with automatic model fallback to avoid hangs.
    """
    def __init__(self, profile_name: str = "master", model: str = "gemini-3.8-flash-medium", timeout: Optional[int] = None):
        self.profile_name = profile_name
        self.model = model
        # No arbitrary wall-clock timeout: Activity Pulse Monitor provides unlimited runtime while active
        self.timeout = None

    def _execute_cli(self, cmd: List[str], prompt: str) -> Tuple[int, str, str]:
        """
        Executes agy non-interactively via --print with NO arbitrary wall-clock timeout (timeout=None).
        Eliminates OS pipe buffer deadlocks by writing stdout/stderr to disk-backed temporary files.
        Monitors token generation pulse in real time. Only pure silence (>180s) triggers self-healing.
        Supports Host Bridge when running inside Linux Docker containers without local agy binary.
        """
        safe_prompt = prompt
        if len(safe_prompt) > 12000:
            safe_prompt = safe_prompt[:12000] + "\n...[Context truncated safely for Windows CLI limit]"

        # Check if agy binary exists locally; if not (e.g. running inside Linux Docker container), call Host Bridge
        import shutil
        if shutil.which("agy") is None:
            import urllib.request
            import urllib.error
            bridge_hosts = [
                os.environ.get("AGY_BRIDGE_URL", "http://host.docker.internal:4002/run"),
                "http://localhost:4002/run"
            ]
            for bridge_url in bridge_hosts:
                try:
                    payload = json.dumps({
                        "model": self.model,
                        "prompt": safe_prompt,
                        "profile_name": self.profile_name
                    }).encode("utf-8")
                    req = urllib.request.Request(bridge_url, data=payload, headers={"Content-Type": "application/json"})
                    with urllib.request.urlopen(req, timeout=600) as resp:
                        res_data = json.loads(resp.read().decode("utf-8"))
                        return res_data.get("returncode", 0), res_data.get("stdout", ""), res_data.get("stderr", "")
                except Exception:
                    continue

        # Create temporary disk-backed output files to guarantee no pipe buffer deadlocks
        out_f = tempfile.NamedTemporaryFile(mode="w+", encoding="utf-8", delete=False)
        err_f = tempfile.NamedTemporaryFile(mode="w+", encoding="utf-8", delete=False)
        out_path = Path(out_f.name)
        err_path = Path(err_f.name)

        # Dedicated turn log file
        turn_id = uuid.uuid4().hex[:8]
        turn_log_path = Path(tempfile.gettempdir()) / f"agy_turn_{turn_id}.log"

        full_cmd = list(cmd) + ["--log-file", str(turn_log_path), "--print", safe_prompt]

        last_activity_time = time.time()
        last_out_size = 0
        last_log_size = 0

        try:
            p = subprocess.Popen(
                full_cmd,
                stdin=subprocess.DEVNULL,
                stdout=out_f,
                stderr=err_f,
                text=True,
                encoding="utf-8",
                errors="replace"
            )

            while True:
                ret = p.poll()
                if ret is not None:
                    break

                time.sleep(2)
                now = time.time()

                cur_out_size = out_path.stat().st_size if out_path.exists() else 0
                cur_log_size = turn_log_path.stat().st_size if turn_log_path.exists() else 0

                if cur_out_size > last_out_size or cur_log_size > last_log_size:
                    last_out_size = cur_out_size
                    last_log_size = cur_log_size
                    last_activity_time = now

                if (now - last_activity_time) > 180:
                    console.print("[bold red][Self-Healing][/bold red] [yellow]ตรวจพบโปรเซส agy หยุดการส่งข้อมูลนานเกิน 3 นาที (True Deadlock) - ทำการกู้คืนระบบอัตโนมัติ...[/yellow]")
                    try:
                        LiveStateManager.get().emit_event("Self-Healing Watchdog", "HEALING", "True deadlock detected (>180s silence). Auto-recovering worker...")
                    except Exception:
                        pass
                    try:
                        subprocess.run(["taskkill", "/F", "/T", "/PID", str(p.pid)], capture_output=True)
                    except Exception:
                        pass
                    return -1, "", "DEADLOCK_RECOVERED: Process was completely silent for 180s."

            out_f.close()
            err_f.close()
            stdout_text = out_path.read_text(encoding="utf-8", errors="replace")
            stderr_text = err_path.read_text(encoding="utf-8", errors="replace")
            return ret, stdout_text.strip(), stderr_text.strip()

        except Exception as e:
            return -1, "", f"EXECUTION_ERROR: {e}"
        finally:
            try:
                out_f.close()
                err_f.close()
                if out_path.exists(): out_path.unlink()
                if err_path.exists(): err_path.unlink()
                if turn_log_path.exists(): turn_log_path.unlink()
            except Exception:
                pass

    def generate(self, system_prompt: str, user_prompt: str) -> str:
        # Check and switch to profile if available
        if AntigravityCredentialManager.has_profile(self.profile_name):
            AntigravityCredentialManager.switch_to_profile(self.profile_name)
        elif self.profile_name == "master" and AntigravityCredentialManager.has_profile("worker"):
            # Fallback to worker if master profile is not yet linked
            AntigravityCredentialManager.switch_to_profile("worker")
        elif self.profile_name == "worker" and AntigravityCredentialManager.has_profile("master"):
            # Fallback to master if worker profile is not yet linked
            AntigravityCredentialManager.switch_to_profile("master")

        combined_prompt = f"{system_prompt}\n\nTask:\n{user_prompt}\n"

        cmd = [
            "agy",
            "--dangerously-skip-permissions",
            "--disable-slash-commands",
            "--model", self.model,
        ]

        # Anti-hang and retry logic for transient glitches
        max_attempts = 2
        for attempt in range(1, max_attempts + 1):
            returncode, stdout, stderr = self._execute_cli(cmd, combined_prompt)

            # Automatic fallback to flash if tier quota is reached
            if "RESOURCE_EXHAUSTED" in stderr or "quota reached" in stderr:
                current_email = AntigravityCredentialManager.get_profile_email(self.profile_name) or self.profile_name
                fallback_model = "gemini-3.8-flash-medium"
                console.print(f"[yellow][!] บัญชี {self.profile_name.upper()} ({current_email}) ไม่สามารถใช้ {self.model} ได้ (โควต้าเฉพาะบัญชีเต็ม) กำลังสลับไปใช้ {fallback_model} ให้อัตโนมัติ...[/yellow]")
                fallback_cmd = [
                    "agy",
                    "--dangerously-skip-permissions",
                    "--disable-slash-commands",
                    "--model", fallback_model,
                ]
                returncode, stdout, stderr = self._execute_cli(fallback_cmd, combined_prompt)

            # Handle Deadlock / Timeout: Self-Healing auto-switches model and retries automatically
            if returncode == -1 or "DEADLOCK" in stderr or "TIMEOUT" in stderr:
                fallback_model = "gemini-3.8-flash-medium"
                console.print(f"[bold yellow][Self-Healing Recovery][/bold yellow] ระบบกู้คืนอัตโนมัติ: สลับไปใช้โมเดลความเร็วสูง {fallback_model} เพื่อแก้ปัญหาค้าง (รอบ {attempt}/{max_attempts})...")
                cmd = [
                    "agy",
                    "--dangerously-skip-permissions",
                    "--disable-slash-commands",
                    "--model", fallback_model,
                ]
                time.sleep(2)
                continue

            if returncode == 0 and stdout:
                return stdout

            # If failed transiently, pause and retry
            if attempt < max_attempts:
                time.sleep(3)
                continue

            if returncode != 0 and not stdout:
                console.print(f"[bold red][!] ข้อผิดพลาดจาก Antigravity CLI ({self.profile_name}):[/bold red] {stderr}")

            return stdout


def get_llm_provider(provider_name: str, model_name: Optional[str] = None) -> BaseLLMProvider:
    """Factory to instantiate the appropriate LLM provider."""
    provider_name = provider_name.lower().strip()
    if provider_name == "mock":
        return MockProvider()
    elif provider_name in ("agy", "agy-cli", "antigravity"):
        model = model_name or "gemini-3.8-flash-medium"
        return AntigravityCLIProvider(profile_name="master", model=model)
    elif provider_name in ("google", "gemini"):
        model = model_name or "gemini-2.5-flash"
        return GoogleGenAIProvider(model_name=model)
    elif provider_name == "openai":
        model = model_name or "gpt-4o"
        return OpenAIProvider(model_name=model)
    elif provider_name in ("anthropic", "claude"):
        model = model_name or "claude-3-5-sonnet-20241022"
        return AnthropicProvider(model_name=model)
    else:
        raise ValueError(f"Unknown LLM provider: {provider_name}. Choose from: agy-cli, mock, google, openai, anthropic.")


