# BLUEPRINT LOADER (Notion & JSON Support)
# ==============================================================================

class BlueprintLoader:
    """Loads and normalizes system blueprints from JSON or Notion exports."""

    @staticmethod
    def load(file_path: Path) -> List[BlueprintTopic]:
        if not file_path.exists():
            raise FileNotFoundError(f"Blueprint file not found at: {file_path}")

        # If Markdown plan file (Borntodev's Loop Engineering plan.md)
        if file_path.suffix.lower() == ".md":
            return BlueprintLoader.load_plan_md(file_path)

        try:
            with open(file_path, "r", encoding="utf-8") as f:
                data = json.load(f)
        except json.JSONDecodeError as e:
            raise ValueError(f"Failed to parse JSON blueprint: {e}")

        # Check if Notion Database export format
        if "results" in data and isinstance(data["results"], list):
            return BlueprintLoader._parse_notion_export(data["results"])

        # Standard blueprint JSON
        topics_data = data.get("topics", [])
        if not isinstance(topics_data, list):
            raise ValueError("Blueprint JSON 'topics' field must be a list.")

        topics: List[BlueprintTopic] = []
        for item in topics_data:
            topic = BlueprintTopic(
                topic_id=int(item.get("topic_id", len(topics) + 1)),
                title=str(item.get("title", f"Topic {len(topics)+1}")),
                description=str(item.get("description", "")),
                target_files=list(item.get("target_files", [])),
                requirements=list(item.get("requirements", [])),
                acceptance_criteria=list(item.get("acceptance_criteria", [])),
                test_commands=list(item.get("test_commands", [])),
            )
            topics.append(topic)

        # Sort sequentially by topic_id
        topics.sort(key=lambda t: t.topic_id)
        return topics

    @staticmethod
    def load_plan_md(file_path: Path) -> List[BlueprintTopic]:
        """
        Parses Borntodev-style plan.md markdown files directly into BlueprintTopics.
        Pillar 8: Persistent Memory & State Tracking.
        """
        plan_text = file_path.read_text(encoding="utf-8")
        pattern = r'- \[([ xX])\] \*\*Topic (?:T|t)?(\d+):\s*(.*?)\*\*(.*?)(?=(?:- \[[ xX]\] \*\*Topic (?:T|t)?\d+:)|(?:---)|\Z)'
        matches = re.findall(pattern, plan_text, re.DOTALL)

        topics: List[BlueprintTopic] = []
        for check, topic_id_str, title, body in matches:
            topic_id = int(topic_id_str)
            
            # Parse Target Files
            tf_match = re.search(r'\*\*Target Files\*\*:\s*([^\n]+)', body)
            target_files: List[str] = []
            if tf_match:
                raw_files = tf_match.group(1).split(',')
                for f in raw_files:
                    clean_f = f.strip('` ').strip()
                    clean_f = re.sub(r'\[([^\]]+)\]\([^\)]+\)', r'\1', clean_f).strip('` ')
                    if clean_f.startswith("output/"):
                        clean_f = clean_f[7:]
                    elif clean_f.startswith("output\\"):
                        clean_f = clean_f[7:]
                    if clean_f:
                        target_files.append(clean_f)

            # Parse DOD (Definition of Done) / Acceptance Criteria
            dod_items: List[str] = []
            dod_block = re.search(r'\*\*DOD\*\*:\s*\n((?:\s+-\s+[^\n]+\n?)+)', body)
            if dod_block:
                dod_items = [re.sub(r'^\s+-\s+', '', l).strip() for l in dod_block.group(1).splitlines() if l.strip()]

            desc = f"Definition of Done (DOD):\n" + "\n".join(f"- {d}" for d in dod_items)

            topic = BlueprintTopic(
                topic_id=topic_id,
                title=title.strip(),
                description=desc,
                target_files=target_files,
                requirements=dod_items,
                acceptance_criteria=dod_items,
                test_commands=[],
            )
            topics.append(topic)

        topics.sort(key=lambda t: t.topic_id)
        return topics

    @staticmethod
    def _parse_notion_export(results: List[Dict[str, Any]]) -> List[BlueprintTopic]:
        """Parses Notion database JSON export format."""
        topics: List[BlueprintTopic] = []
        for idx, row in enumerate(results, start=1):
            props = row.get("properties", {})
            
            # Extract title
            title = ""
            for key in ["Name", "Title", "Topic"]:
                if key in props and "title" in props[key]:
                    parts = props[key]["title"]
                    title = "".join(p.get("plain_text", "") for p in parts)
                    if title: break
            if not title:
                title = f"Notion Checklist Item {idx}"

            # Extract topic_id
            topic_id = idx
            if "Topic ID" in props and "number" in props["Topic ID"]:
                topic_id = props["Topic ID"]["number"] or idx

            # Extract target files
            target_files = []
            if "Target Files" in props and "multi_select" in props["Target Files"]:
                target_files = [item["name"] for item in props["Target Files"]["multi_select"]]

            # Extract requirements
            requirements = []
            for rkey in ["Requirements", "Description", "Details"]:
                if rkey in props and "rich_text" in props[rkey]:
                    text = "".join(p.get("plain_text", "") for p in props[rkey]["rich_text"])
                    if text:
                        requirements = [line.strip("- *") for line in text.splitlines() if line.strip()]
                        break

            topics.append(
                BlueprintTopic(
                    topic_id=topic_id,
                    title=title,
                    description=f"Imported from Notion checklist (Row {idx})",
                    target_files=target_files or [f"src/topic_{topic_id}.js"],
                    requirements=requirements or ["Implement component per specifications."],
                    acceptance_criteria=["File must exist and compile cleanly."],
                )
            )
        topics.sort(key=lambda t: t.topic_id)
        return topics


