class Agent1OrchestratorQA:
    """
    Agent 1 (Orchestrator / Notion Master & QA Tester):
    - Holds the full system blueprint.
    - Dispatches one topic at a time to Agent 2.
    - Evaluates code written by Agent 2 against blueprint criteria & UX requirements.
    - Executes terminal test commands and captures logs.
    - If criteria unmet, generates specific feedback points and instructs Agent 2 to iterate.
    """

    SYSTEM_PROMPT = """You are Agent 1 (Orchestrator & Senior Frontend QA Tester).
Your mission is to evaluate code submitted by Agent 2 against strict blueprint acceptance criteria,
modern UI/UX design standards, accessibility (WCAG AA/AAA), and responsive design principles.

CRITICAL ARCHITECTURAL & DESIGN DIRECTIVES:
- FRONTEND ONLY (หน้าบ้านล้วนๆ): This system is 100% client-side Frontend UI/UX (HTML5, Modern CSS, Client-Side JavaScript).
- Do NOT request or expect backend, server-side APIs, Node/Express, Python web servers, or databases.
- All interactive features (tabs, modals, flow simulator, ingredient basket, filters) must execute entirely in the browser.
- STRICT DESIGN SYSTEM & PALETTE (mewteetawat.com V6.3 Theme from index.html):
  * Background: --v6-paper (#fbfaf8)
  * Secondary / Panel: --v6-soft (#f4f2ee) and #ffffff
  * Lines / Borders: --v6-line (#e7e3de)
  * Primary Text & Headings: --v6-ink (#11110f)
  * Muted Text: --v6-muted (#6b6762)
  * Brand Coral: --v6-coral (#ed765b) - used as top 4px accent bar on cards and highlights
  * Coral Kicker: --v6-coral-text (#ae4f3a) - eyebrow text, active category tabs
  * Electric Violet: --v6-violet (#8a76ff) - secondary status badges
  * Gradient Text: linear-gradient(90deg, #ef8a68, #8f7cff, #6fa1ff)
  * Fonts: Google Fonts 'Inter', 'Prompt', 'Noto Sans Thai', sans-serif
  * Cards: .mew-offer-card style (white bg, 1px border #e7e3de, top 4px accent bar in coral or violet, soft shadow 0 18px 50px rgba(17,17,15,0.05), hover translateY(-2px))
  * Buttons: Primary CTA dark ink #11110f with white text and pill rounded shape. Ghost button with white background and #e7e3de border.
- STRICT NEGATIVE CONSTRAINT:
  * Absolutely NO fake or arbitrary statistics like "12 สัปดาห์", "+12 สัปดาห์นี้", "12 สัปดาห์วิเคราะห์แล้ว", or fake growth percentage badges.
  * Keep the interface clean, functional, elegant, easy to scan and use. Reject any code with fake metric badges.

When performing a QA evaluation, return a valid JSON object matching this schema:
{
  "passed": true | false,
  "score": 0-100,
  "feedback_points": [
    "Specific issue 1...",
    "Specific issue 2..."
  ],
  "summary": "Brief summary of QA evaluation."
}
Only output the JSON object with no surrounding conversational text."""

    def __init__(self, topics: List[BlueprintTopic], llm: BaseLLMProvider):
        self.topics = topics
        self.llm = llm

    def build_dispatch_prompt(
        self,
        topic: BlueprintTopic,
        iteration: int,
        max_iterations: int,
        previous_qa: Optional[QAEvaluation],
        workspace_dir: Path,
    ) -> str:
        """Constructs the prompt for Agent 2, including self-correction logs if iterating."""
        prompt_parts: List[str] = []

        prompt_parts.append(f"# DISPATCH: TOPIC {topic.topic_id} - {topic.title}")
        prompt_parts.append(f"Description: {topic.description}\n")

        # In case of iteration > 1: Inject exact QA feedback & terminal logs for self-correction
        if iteration > 1 and previous_qa:
            prompt_parts.append("=" * 80)
            prompt_parts.append(f"[!] CRITICAL: REVISION REQUIRED (Iteration {iteration} of {max_iterations})")
            prompt_parts.append("Your previous implementation did NOT pass QA evaluation. Fix all issues below:")
            prompt_parts.append("")
            
            if previous_qa.feedback_points:
                prompt_parts.append("### QA FEEDBACK POINTS:")
                for pt in previous_qa.feedback_points:
                    prompt_parts.append(f"  * {pt}")
                prompt_parts.append("")

            if previous_qa.terminal_errors:
                prompt_parts.append("### TERMINAL TEST FAILURE LOGS:")
                for err in previous_qa.terminal_errors:
                    prompt_parts.append(f"```text\n{err.strip()}\n```")
                prompt_parts.append("")

            # Provide existing file content for reference/update
            prompt_parts.append("### CURRENT FILE CONTENTS ON DISK:")
            for rel_file in topic.target_files:
                file_path = workspace_dir / rel_file
                if file_path.exists():
                    try:
                        content = file_path.read_text(encoding="utf-8")
                        if len(content) > 3000:
                            content = content[:2000] + f"\n... [Truncated {len(content) - 3000} chars: full file is at {rel_file}] ...\n" + content[-1000:]
                        prompt_parts.append(f"--- File: {rel_file} ---\n{content}\n")
                    except Exception:
                        pass
            prompt_parts.append("=" * 80 + "\n")

        prompt_parts.append("### TARGET FILES TO CREATE OR UPDATE:")
        for f in topic.target_files:
            prompt_parts.append(f"- {f}")
        prompt_parts.append("")

        prompt_parts.append("### UX/UI & FUNCTIONAL REQUIREMENTS:")
        for req in topic.requirements:
            prompt_parts.append(f"- {req}")
        prompt_parts.append("")

        prompt_parts.append("### ACCEPTANCE CRITERIA:")
        for ac in topic.acceptance_criteria:
            prompt_parts.append(f"- {ac}")
        prompt_parts.append("")

        prompt_parts.append("### INSTRUCTIONS FOR AGENT 2:")
        prompt_parts.append("1. PURE FRONTEND ONLY (หน้าบ้านล้วนๆ): Write clean, production-ready HTML5, CSS3, and client-side JavaScript.")
        prompt_parts.append("   - Do NOT write any backend/server code, Node.js servers, or databases.")
        prompt_parts.append("   - All interactivity (tabs, modals, flow simulator, filters, basket, concept generation preview) must execute client-side in the browser.")
        prompt_parts.append("2. DESIGN SYSTEM & COLOR THEME (mewteetawat.com V6.3 from index.html):")
        prompt_parts.append("   - Palette: Paper Canvas #fbfaf8, Soft Card #f4f2ee, Stone Lines #e7e3de, Deep Ink #11110f, Muted #6b6762, Accent Coral #ed765b, Kicker Coral #ae4f3a, Electric Violet #8a76ff.")
        prompt_parts.append("   - Cards: .mew-offer-card style with a 4px top accent bar in coral or violet, 1px line border, and soft shadow.")
        prompt_parts.append("   - Buttons: Deep Ink #11110f with white text and pill rounded shape. Ghost button with white background and line border.")
        prompt_parts.append("   - Micro-interactions: hover translateY(-2px), smooth transitions.")
        prompt_parts.append("3. STRICT NEGATIVE CONSTRAINT (คำสั่งห้ามเด็ดขาด):")
        prompt_parts.append("   - Absolutely DO NOT put fake/arbitrary statistics like '12 สัปดาห์', '+12 สัปดาห์นี้', '12 สัปดาห์วิเคราะห์แล้ว', or fake percentage badges.")
        prompt_parts.append("   - Keep the interface clean, functional, elegant, and directly usable.")
        prompt_parts.append("4. Output EVERY target file using this exact delimiter format:")
        prompt_parts.append("### FILE: path/to/file.ext")
        prompt_parts.append("/* code goes here */")
        prompt_parts.append("### END_FILE")
        prompt_parts.append("5. Do not omit code with comments like '// rest of code stays same'. Output complete files.")

        return "\n".join(prompt_parts)

    def execute_terminal_validation(self, topic: BlueprintTopic, workspace_dir: Path) -> Tuple[bool, List[str], str]:
        """
        Runs the terminal test commands and automatic deterministic code validation.
        (Pillar 5 in Borntodev's Loop Engineering: Deterministic Tests to Prevent Doom Loops)
        """
        all_passed = True
        error_logs: List[str] = []
        stdout_logs: List[str] = []

        # 1. Automatic JS Syntax & Integrity Check via Node
        for rel_file in topic.target_files:
            if rel_file.endswith(".js"):
                js_path = workspace_dir / rel_file
                if js_path.exists():
                    try:
                        check_proc = subprocess.run(
                            f'node -c "{js_path}"',
                            shell=True,
                            capture_output=True,
                            text=True,
                            encoding="utf-8",
                            errors="replace",
                            timeout=10,
                        )
                        if check_proc.returncode != 0:
                            all_passed = False
                            error_logs.append(f"JavaScript Syntax Error in {rel_file}:\n{check_proc.stderr or check_proc.stdout}")
                        else:
                            stdout_logs.append(f"Node.js Syntax Validated: {rel_file}")
                    except Exception:
                        pass

        # 1.5 Auto-execute any unit test files (*.test.js) in target files or workspace
        for rel_file in topic.target_files:
            if rel_file.endswith(".test.js"):
                test_path = workspace_dir / rel_file
                if test_path.exists():
                    try:
                        t_proc = subprocess.run(
                            f'node --test "{test_path}"',
                            shell=True,
                            capture_output=True,
                            text=True,
                            encoding="utf-8",
                            errors="replace",
                            timeout=25,
                        )
                        if t_proc.returncode != 0:
                            all_passed = False
                            error_logs.append(f"Unit Test Failed in {rel_file}:\n{t_proc.stderr or t_proc.stdout}")
                        else:
                            stdout_logs.append(f"Unit Test Passed: {rel_file}")
                    except Exception as e:
                        all_passed = False
                        error_logs.append(f"Unit Test Error in {rel_file}: {e}")

        # 1.6 Verify expected data-testid in HTML files if specified in DOD
        expected_testids = re.findall(r'data-testid=["\']([^"\']+)["\']', topic.description)
        if expected_testids:
            html_contents = []
            for rel_file in topic.target_files:
                if rel_file.endswith(".html"):
                    h_path = workspace_dir / rel_file
                    if h_path.exists():
                        try:
                            html_contents.append(h_path.read_text(encoding="utf-8"))
                        except Exception:
                            pass
            combined_html = "\n".join(html_contents)
            missing_testids = [tid for tid in expected_testids if tid not in combined_html]
            if missing_testids and html_contents:
                all_passed = False
                error_logs.append(f"Missing required data-testid in HTML: {', '.join(missing_testids)}")

        # 2. Execute explicit terminal test commands configured in the topic
        for cmd in topic.test_commands:
            try:
                # Execute in project context
                proc = subprocess.run(
                    cmd,
                    shell=True,
                    capture_output=True,
                    text=True,
                    encoding="utf-8",
                    errors="replace",
                    timeout=30,
                    cwd=str(workspace_dir.parent if workspace_dir.name == "output" else workspace_dir),
                )
                if proc.returncode != 0:
                    all_passed = False
                    err_msg = f"Command failed: {cmd}\nExit code: {proc.returncode}\nStderr: {proc.stderr}\nStdout: {proc.stdout}"
                    error_logs.append(err_msg)
                else:
                    stdout_logs.append(f"PASSED: {cmd}\nOutput: {proc.stdout.strip()}")
            except subprocess.TimeoutExpired:
                all_passed = False
                error_logs.append(f"Command timed out after 30s: {cmd}")
            except Exception as e:
                all_passed = False
                error_logs.append(f"Command error: {cmd} - {str(e)}")

        return all_passed, error_logs, "\n".join(stdout_logs)

    def evaluate_submission(
        self,
        topic: BlueprintTopic,
        worker_output: WorkerOutput,
        workspace_dir: Path,
    ) -> QAEvaluation:
        """
        Evaluates Agent 2's code against:
        1. File existence and non-empty check
        2. Terminal test validation commands
        3. Blueprint & UX/UI criteria via QA review
        """
        feedback_points: List[str] = []

        # 1. Physical file check
        missing_files = []
        for rel_file in topic.target_files:
            target_path = workspace_dir / rel_file
            if not target_path.exists():
                missing_files.append(rel_file)
            elif target_path.stat().st_size == 0:
                missing_files.append(f"{rel_file} (file is empty)")

        if missing_files:
            feedback_points.append(f"Target files were not created on disk: {', '.join(missing_files)}")

        # 2. Terminal test commands
        test_passed, test_errors, test_stdout = self.execute_terminal_validation(topic, workspace_dir)
        if not test_passed:
            feedback_points.append("Automated terminal test validation suite failed.")

        # 3. LLM QA Review (if mock, MockProvider handles rules; if real LLM, calls QA prompt)
        qa_prompt = f"""Evaluate the following submitted code files for Topic {topic.topic_id} against the blueprint requirements.

Blueprint Requirements:
{json.dumps(topic.requirements, indent=2)}

Acceptance Criteria:
{json.dumps(topic.acceptance_criteria, indent=2)}

Terminal Validation Errors:
{json.dumps(test_errors, indent=2)}

Submitted Files:
"""
        for rel_file, content in worker_output.files_written.items():
            qa_prompt += f"\n--- {rel_file} ---\n{content}\n"

        try:
            qa_raw = self.llm.generate(self.SYSTEM_PROMPT, qa_prompt)
            # Parse JSON from response
            cleaned_json = re.search(r"\{.*\}", qa_raw, re.DOTALL)
            if cleaned_json:
                qa_data = json.loads(cleaned_json.group(0))
                passed_llm = qa_data.get("passed", False)
                llm_points = qa_data.get("feedback_points", [])
                summary = qa_data.get("summary", "")
                if not passed_llm:
                    feedback_points.extend(llm_points)
            else:
                passed_llm = test_passed and len(missing_files) == 0
                summary = "Automated rule validation applied."
        except Exception as e:
            # Fallback to test results if LLM evaluation fails to parse
            passed_llm = test_passed and len(missing_files) == 0
            summary = f"Rule-based evaluation fallback: {e}"

        overall_passed = (len(missing_files) == 0) and test_passed and (len(feedback_points) == 0)

        return QAEvaluation(
            passed=overall_passed,
            feedback_points=feedback_points,
            terminal_errors=test_errors,
            terminal_stdout=test_stdout,
            summary=summary,
        )

    def check_existing_solution(self, topic: BlueprintTopic, workspace_dir: Path) -> Optional[QAEvaluation]:
        """
        Agent 1 Autonomous Pre-check:
        Evaluates whether the topic's target files already exist on disk and pass automated terminal tests.
        If passed, approves immediately without asking Agent 2 to recreate them from scratch.
        """
        for rel_file in topic.target_files:
            target_path = workspace_dir / rel_file
            if not target_path.exists() or target_path.stat().st_size == 0:
                return None

        test_passed, test_errors, test_stdout = self.execute_terminal_validation(topic, workspace_dir)
        if not test_passed:
            return None

        return QAEvaluation(
            passed=True,
            feedback_points=[],
            terminal_errors=[],
            terminal_stdout=test_stdout,
            summary=f"พบไฟล์บนดิสก์ครบถ้วน ({', '.join(topic.target_files)}) และผ่านการทดสอบอัตโนมัติแล้ว",
        )


