class Agent2WorkerCoder:
    """
    Agent 2 (Worker / Frontend & UX-UI Coder):
    - Receives specific topic & requirements from Agent 1.
    - Receives QA feedback & terminal logs on retries.
    - Writes, updates, and saves actual UI/UX code files to disk.
    - Returns execution status and file manifest back to Agent 1.
    """

    SYSTEM_PROMPT = """You are Agent 2 (Worker / Senior Frontend & UX-UI Engineer).
Your role is to write clean, modular, accessible, responsive, and robust FRONTEND UI/UX code (หน้าบ้านล้วนๆ).

CRITICAL DIRECTIVE:
- PURE FRONTEND ONLY: Focus 100% on HTML5, Modern CSS, and Client-Side Vanilla JavaScript (ES6+).
- Absolutely NO backend/server code, NO Node/Express, NO Python backends, NO database setup.
- All interactivity (tabs, modals, flow simulator, multi-ingredient basket, concept synthesis preview) must be implemented purely client-side in the browser.

DESIGN SYSTEM & PALETTE (mewteetawat.com V6.3 Theme from index.html):
- Palette: Paper/Canvas #fbfaf8, Soft Surface #f4f2ee, Stone Line #e7e3de, Deep Ink #11110f, Muted #6b6762, Accent Coral #ed765b, Kicker Coral #ae4f3a, Electric Violet #8a76ff.
- Typography: Use Google Fonts 'Inter', 'Prompt', 'Noto Sans Thai', sans-serif.
- Cards: .mew-offer-card style (white background #ffffff, 1px border #e7e3de, 4px top accent bar in coral or violet, soft shadow 0 18px 50px rgba(17,17,15,0.05), hover translateY(-2px)).
- Buttons: Primary CTA deep ink #11110f with white text and pill rounded shape. Ghost button with white background and line border.
- Animations: Smooth subtleSlideUp animation, hover translateY(-2px).

STRICT NEGATIVE CONSTRAINT (คำสั่งห้ามเด็ดขาด):
- Absolutely DO NOT put fake or arbitrary statistics like "12 สัปดาห์", "+12 สัปดาห์นี้", "12 สัปดาห์วิเคราะห์แล้ว", or fake percentage badges.
- Keep the interface clean, functional, elegant, and directly usable without fluff.

Core Principles:
- Accessible UI: Follow WCAG AA/AAA guidelines, ARIA landmarks, semantic HTML, and focus states.
- Clean Modern CSS: Use custom properties, fluid layouts, flex/grid, and reduced-motion queries.
- Clean JavaScript: Follow modern ES6+ standards, handle keyboard events (Escape, Enter, Tab).

Output Format Requirement:
You MUST output all code files wrapped in exact delimiter blocks:
### FILE: relative/path/to/file.ext
[File contents here]
### END_FILE

Ensure complete, copy-pasteable, production-ready code. Do not use placeholders."""

    def __init__(self, llm: BaseLLMProvider):
        self.llm = llm

    def execute_and_save(self, dispatch_prompt: str, workspace_dir: Path) -> WorkerOutput:
        """Calls LLM, extracts code files, saves them to disk, and returns manifest."""
        raw_response = self.llm.generate(self.SYSTEM_PROMPT, dispatch_prompt)
        files_written = self._parse_and_write_files(raw_response, workspace_dir)
        return WorkerOutput(
            files_written=files_written,
            notes="Files written to workspace.",
            raw_response=raw_response,
        )

    def _parse_and_write_files(self, response_text: str, workspace_dir: Path) -> Dict[str, str]:
        """Parses files delimited by '### FILE: <path>' ... '### END_FILE' and saves them."""
        files_map: Dict[str, str] = {}
        workspace_dir.mkdir(parents=True, exist_ok=True)

        # Regex for delimited blocks
        pattern = r"### FILE:\s*([^\n\r]+)\r?\n(.*?)(?:### END_FILE|(?=### FILE:)|\Z)"
        matches = re.findall(pattern, response_text, re.DOTALL)

        if not matches:
            # Fallback pattern: ```css /* filepath: ... */ or markdown header
            markdown_pattern = r"```(?:\w+)?\s*(?:/\*|<!--|//)?\s*(?:filepath:|file:)\s*([^\n\r]+?)(?:\*/|-->)?\r?\n(.*?)```"
            matches = re.findall(markdown_pattern, response_text, re.DOTALL)

        for filepath_str, content in matches:
            filepath_clean = filepath_str.strip().strip("'\"` ")
            # Sanitize path to prevent directory traversal
            clean_path = Path(filepath_clean)
            if clean_path.is_absolute() or ".." in clean_path.parts:
                clean_path = Path(*[p for p in clean_path.parts if p != ".."])

            full_path = workspace_dir / clean_path
            full_path.parent.mkdir(parents=True, exist_ok=True)
            
            # Strip accidental Markdown code fences (e.g. ```javascript ... ```)
            clean_lines = content.splitlines()
            if clean_lines and clean_lines[0].strip().startswith("```"):
                clean_lines = clean_lines[1:]
            if clean_lines and clean_lines[-1].strip() == "```":
                clean_lines = clean_lines[:-1]
            normalized_content = "\n".join(clean_lines).strip("\r\n") + "\n"
            full_path.write_text(normalized_content, encoding="utf-8")
            files_map[filepath_clean] = normalized_content

        return files_map


# ==============================================================================
# CLOSED-LOOP ENGINE
# ==============================================================================

class ClosedLoopEngine:
    """
    Coordinates the 2-Agent Closed Loop:
    - Topic Progression: Topic N -> Test & Approve -> Topic N+1.
    - Max Iterations: 3 to 5 attempts per topic to prevent infinite retry loops.
    - Self-Correction: Injects exact error logs and QA feedback on retries.
    - Target Scope: Controls execution from start_topic_id to end_topic_id.
    """

    def __init__(
        self,
        blueprint_path: Path,
        workspace_dir: Path,
        orchestrator_llm: BaseLLMProvider,
        worker_llm: Optional[BaseLLMProvider] = None,
        max_iterations: int = 3,
        halt_on_fail: bool = False,
        force_rebuild: bool = False,
    ):
        self.blueprint_path = blueprint_path
        self.workspace_dir = workspace_dir
        self.orchestrator_llm = orchestrator_llm
        self.worker_llm = worker_llm or orchestrator_llm
        self.max_iterations = max(1, min(max_iterations, 10))  # Clamped between 1 and 10
        self.halt_on_fail = halt_on_fail
        self.force_rebuild = force_rebuild

        # Load blueprint
        self.topics = BlueprintLoader.load(self.blueprint_path)
        self.orchestrator = Agent1OrchestratorQA(self.topics, self.orchestrator_llm)
        self.worker = Agent2WorkerCoder(self.worker_llm)

    def run(self, start_topic_id: Optional[int] = None, end_topic_id: Optional[int] = None) -> List[TopicRunReport]:
        """Executes the closed loop over the selected range of topics."""
        if not self.topics:
            console.print("[yellow][!] ไฟล์ Blueprint ว่างอยู่ (ยังไม่มีหัวข้องาน) กรุณาใส่หัวข้อหรือส่งไฟล์งานก่อนเริ่มรันครับ[/yellow]")
            return []

        # Filter topic scope
        filtered_topics = [
            t for t in self.topics
            if (start_topic_id is None or t.topic_id >= start_topic_id)
            and (end_topic_id is None or t.topic_id <= end_topic_id)
        ]

        if not filtered_topics:
            console.print("[bold red][!] ไม่พบหัวข้อที่ตรงกับช่วงสโคปที่ระบุ[/bold red]")
            return []

        self._print_header(filtered_topics)
        reports: List[TopicRunReport] = []

        # Check which topics are already marked [x] in plan.md
        plan_done_ids = set()
        plan_file = Path("plan.md")
        if not plan_file.exists():
            plan_file = self.workspace_dir.parent / "plan.md"
        if plan_file.exists():
            p_text = plan_file.read_text(encoding="utf-8")
            for m in re.finditer(r'- \[x\] \*\*Topic (?:T|t)?(\d+):', p_text, re.IGNORECASE):
                plan_done_ids.add(int(m.group(1)))

        for topic_idx, topic in enumerate(filtered_topics, start=1):
            console.print(Rule(f"[bold cyan]📌 หัวข้อที่ {topic.topic_id}: {topic.title}[/bold cyan]", style="cyan"))
            console.print(f"[dim]{topic.description}[/dim]\n")

            # Agent 1 Autonomous Pre-check: ตรวจสอบก่อนว่าหัวข้อนี้มาร์ก [x] ใน plan.md และเขียนเสร็จแล้วหรือไม่
            live_mgr = LiveStateManager.get(self.workspace_dir)
            if not self.force_rebuild and topic.topic_id in plan_done_ids:
                existing_qa = self.orchestrator.check_existing_solution(topic, self.workspace_dir)
                if existing_qa and existing_qa.passed:
                    live_mgr.set_approved(topic.topic_id, topic.title, 0, topic.target_files, existing_qa.summary)
                    console.print(Panel(
                        f"[bold green][PASS] Agent 1 ตรวจสอบพบงานเดิมสำเร็จแล้ว: หัวข้อที่ {topic.topic_id} ผ่านการทดสอบเรียบร้อยแล้ว![/bold green]\n"
                        f"[dim]{existing_qa.summary}[/dim]\n"
                        f"[dim]ไฟล์บนดิสก์: {', '.join(topic.target_files)} — ข้ามไปหัวข้อถัดไปทันทีโดยไม่ต้องเขียนซ้ำ[/dim]",
                        title="[bold green]Agent 1 อนุมัติผ่านการตรวจสอบเดิม (Already Approved)[/bold green]",
                        border_style="green",
                    ))
                    reports.append(
                        TopicRunReport(
                            topic_id=topic.topic_id,
                            title=topic.title,
                            status="APPROVED",
                            iterations_used=0,
                            files_created=topic.target_files,
                            final_feedback=existing_qa.summary,
                        )
                    )
                    console.print()
                    continue

            iteration = 1
            previous_qa: Optional[QAEvaluation] = None
            topic_approved = False
            last_files_created: List[str] = []
            final_feedback = ""

            # Publish real-time state for Live & Mobile Web Dashboards
            live_mgr = LiveStateManager.get(self.workspace_dir)
            live_mgr.set_topic_start(topic.topic_id, topic.title, iteration, self.max_iterations, topic.target_files)

            while iteration <= self.max_iterations:
                console.print(
                    f"[bold yellow][*] รอบที่ {iteration}/{self.max_iterations}[/bold yellow] - "
                    f"Agent 1 กำลังสั่งงานหัวข้อที่ {topic.topic_id}..."
                )

                # 1. Agent 1 formats prompt for Agent 2 (with feedback if iteration > 1)
                dispatch_prompt = self.orchestrator.build_dispatch_prompt(
                    topic=topic,
                    iteration=iteration,
                    max_iterations=self.max_iterations,
                    previous_qa=previous_qa,
                    workspace_dir=self.workspace_dir,
                )

                # 2. Agent 2 generates and saves code files
                live_mgr.set_stage("WORKER_CODING")
                with active_status_timer(f"[cyan]Agent 2 (ช่างเขียนโค้ด) กำลังเขียนโค้ดหัวข้อที่ {topic.topic_id}...[/cyan]"):
                    worker_output = self.worker.execute_and_save(dispatch_prompt, self.workspace_dir)

                last_files_created = list(worker_output.files_written.keys())
                console.print(f"[green][+] Agent 2 บันทึกไฟล์เสร็จสิ้น {len(last_files_created)} ไฟล์:[/green] "
                              f"{', '.join(last_files_created) if last_files_created else '[red]ไม่มีไฟล์[/red]'}")

                # 3. Agent 1 evaluates code & terminal tests
                live_mgr.set_stage("QA_TESTING")
                with active_status_timer(f"[cyan]Agent 1 (QA Tester) กำลังรัน Terminal Test และตรวจสอบคุณภาพโค้ด...[/cyan]"):
                    qa_result = self.orchestrator.evaluate_submission(topic, worker_output, self.workspace_dir)

                previous_qa = qa_result
                final_feedback = qa_result.summary

                # 4. Check approval
                if qa_result.passed:
                    topic_approved = True
                    live_mgr.set_approved(topic.topic_id, topic.title, iteration, last_files_created, qa_result.summary)
                    console.print(Panel(
                        f"[bold green][PASS] อนุมัติ: หัวข้อที่ {topic.topic_id} ผ่านการตรวจสอบและทดสอบในรอบที่ {iteration} เรียบร้อยแล้ว![/bold green]\n"
                        f"[dim]{qa_result.summary}[/dim]",
                        title="[bold green]Agent 1 อนุมัติผ่านการตรวจสอบ (QA Approved)[/bold green]",
                        border_style="green",
                    ))
                    break
                else:
                    live_mgr.set_retry(topic.topic_id, iteration, "; ".join(qa_result.feedback_points))
                    console.print(Panel(
                        f"[bold red][FAIL] ไม่ผ่านการตรวจสอบ: หัวข้อที่ {topic.topic_id} ในรอบที่ {iteration}[/bold red]\n\n"
                        + "\n".join(f"[yellow]* {pt}[/yellow]" for pt in qa_result.feedback_points)
                        + (f"\n\n[bold red]ข้อผิดพลาดจาก Terminal Test:[/bold red]\n" + "\n".join(qa_result.terminal_errors) if qa_result.terminal_errors else ""),
                        title=f"[bold red]Agent 1 สั่งแก้ไขโค้ด (ความพยายามรอบที่ {iteration}/{self.max_iterations})[/bold red]",
                        border_style="red",
                    ))

                    if iteration == self.max_iterations:
                        console.print(
                            f"[bold red][!] ระบบป้องกันทำงาน:[/bold red] ครบจำนวนรอบสูงสุด ({self.max_iterations}) "
                            f"สำหรับหัวข้อที่ {topic.topic_id} แล้ว ข้ามไปหัวข้อถัดไป\n"
                        )
                        break

                    console.print("[dim]🔄 กำลังส่ง Error Logs และฟีดแบ็กกลับไปให้ Agent 2 แก้ไขโค้ดรอบถัดไปอัตโนมัติ...[/dim]\n")
                    iteration += 1

            # Record report for this topic
            status_label = "APPROVED" if topic_approved else "FAILED"
            rep = TopicRunReport(
                topic_id=topic.topic_id,
                title=topic.title,
                status=status_label,
                iterations_used=iteration if topic_approved else self.max_iterations,
                files_created=last_files_created,
                final_feedback=final_feedback,
            )
            reports.append(rep)

            # Immediately synchronize persistent memory for this topic into plan.md in real time
            try:
                self._sync_single_topic(rep)
            except Exception as e:
                console.print(f"[dim][*] Real-time topic sync notice: {e}[/dim]")

            if not topic_approved and self.halt_on_fail:
                console.print(f"[bold red]หยุดการทำงานเนื่องจากหัวข้อที่ {topic.topic_id} ไม่ผ่าน และเปิดใช้งาน halt_on_fail ไว้[/bold red]")
                break

            console.print()  # Spacer between topics

        # Automatically assemble all generated components into the main index.html App Shell
        try:
            self._assemble_index_html()
        except Exception as e:
            console.print(f"[dim][*] Auto-assembly notice: {e}[/dim]")

        # Automatically synchronize persistent memory into plan.md (Borntodev Pillar 8)
        try:
            self._sync_plan_md(reports)
        except Exception as e:
            console.print(f"[dim][*] Persistent memory sync notice: {e}[/dim]")

        self._print_summary(reports)
        return reports

    def _assemble_index_html(self) -> None:
        """
        Integrates all modular component HTMLs into the main index.html App Shell
        so that every tab (Overview, Research, Library, Remix, Board) renders live without placeholder cards.
        """
        index_file = self.workspace_dir / "src" / "index.html"
        if not index_file.exists():
            index_file = self.workspace_dir / "index.html"
        if not index_file.exists():
            return

        base = index_file.parent
        index_text = index_file.read_text(encoding="utf-8")

        # 1. Update <head> with component stylesheets
        css_links = """  <!-- Component Stylesheets -->
  <link rel="stylesheet" href="styles/main.css">
  <link rel="stylesheet" href="styles/onboarding.css">
  <link rel="stylesheet" href="styles/research.css">
  <link rel="stylesheet" href="styles/save_modal.css">
  <link rel="stylesheet" href="styles/library.css">
  <link rel="stylesheet" href="styles/remix.css">
  <link rel="stylesheet" href="styles/content_board.css">"""

        if 'styles/research.css' not in index_text:
            index_text = index_text.replace('<link rel="stylesheet" href="styles/main.css">', css_links)
        elif 'styles/onboarding.css' not in index_text:
            index_text = index_text.replace('<link rel="stylesheet" href="styles/research.css">', '<link rel="stylesheet" href="styles/onboarding.css">\n  <link rel="stylesheet" href="styles/research.css">')

        # Add Brand Brain Button in header if not present
        if 'btn-header-brand-brain' not in index_text and '<div class="app-header-utilities">' in index_text:
            brand_btn = """<button type="button" id="btn-header-brand-brain" class="btn-pill btn-ghost" onclick="window.openOnboardingModal()" title="ตั้งค่าข้อมูลสินค้าและ Brand Brain" style="font-size: 0.75rem; padding: 0.35rem 0.75rem; border: 1.5px solid rgba(22,22,24,0.12); display: flex; align-items: center; gap: 0.35rem; cursor: pointer;">
            <span>🧠</span>
            <span id="header-brand-name">Brand Brain</span>
          </button>"""
            index_text = index_text.replace('<div class="app-header-utilities">', f'<div class="app-header-utilities">\n          {brand_btn}')

        # 2. Integrate component sections
        components_map = {
            'view-research': ('components/research.html', 'research-heading'),
            'view-library': ('components/library.html', 'library-heading'),
            'view-remix': ('components/remix.html', 'remix-heading'),
            'view-board': ('components/content_board.html', 'board-heading'),
        }

        for view_id, (comp_rel, heading_id) in components_map.items():
            comp_path = base / comp_rel
            if comp_path.exists():
                comp_html = comp_path.read_text(encoding="utf-8")
                marker_pattern = rf'<!-- START:{view_id} -->.*?<!-- END:{view_id} -->'
                if re.search(marker_pattern, index_text, flags=re.DOTALL):
                    index_text = re.sub(marker_pattern, f'<!-- START:{view_id} -->\n{comp_html}\n<!-- END:{view_id} -->', index_text, flags=re.DOTALL)
                else:
                    pattern = rf'<section id="{view_id}" class="view-section"[^>]*>.*?</section>'
                    replacement = f'<section id="{view_id}" class="view-section" aria-labelledby="{heading_id}">\n<!-- START:{view_id} -->\n{comp_html}\n<!-- END:{view_id} -->\n      </section>'
                    index_text = re.sub(pattern, replacement, index_text, flags=re.DOTALL)

        # 3. Add or update Onboarding Modal & Save Modal & scripts
        onboarding_path = base / "components/onboarding.html"
        if onboarding_path.exists():
            onboarding_html = onboarding_path.read_text(encoding="utf-8")
            if 'id="onboarding-modal"' in index_text:
                index_text = re.sub(r'<div class="onboarding-overlay" id="onboarding-modal".*?</div>(?=\s*<main class="app-main")', onboarding_html, index_text, flags=re.DOTALL)
            else:
                index_text = index_text.replace('<main class="app-main"', f'{onboarding_html}\n\n    <main class="app-main"')

        modal_path = base / "components/save_modal.html"
        if modal_path.exists() and 'save-decision-modal' not in index_text:
            modal_html = modal_path.read_text(encoding="utf-8")
            scripts_and_modal = f"""
    <!-- Human Save Decision Modal (S03) -->
    {modal_html}

    <!-- Component Modules -->
    <script src="modules/router.js"></script>
    <script src="modules/onboarding.js"></script>
    <script src="modules/research.js"></script>
    <script src="modules/save_modal.js"></script>
    <script src="modules/library.js"></script>
    <script src="modules/remix.js"></script>
    <script src="modules/content_board.js"></script>
</body>"""
            index_text = index_text.replace('</body>', scripts_and_modal)
        elif 'modules/onboarding.js' not in index_text:
            index_text = index_text.replace('<script src="modules/research.js"></script>', '<script src="modules/onboarding.js"></script>\n    <script src="modules/research.js"></script>')

        index_file.write_text(index_text, encoding="utf-8")

    def _sync_single_topic(self, rep: TopicRunReport) -> None:
        plan_file = Path("plan.md")
        if not plan_file.exists():
            plan_file = self.workspace_dir.parent / "plan.md"
        if not plan_file.exists():
            return

        plan_text = plan_file.read_text(encoding="utf-8")
        if rep.status == "APPROVED":
            pattern = rf'- \[[ xX]\] \*\*Topic (?:T|t)?0*{rep.topic_id}:'
            replacement = f'- [x] **Topic T{rep.topic_id:02d}:'
            plan_text = re.sub(pattern, replacement, plan_text)
            # Update status text if present
            plan_text = re.sub(rf'(- \*\*Topic T{rep.topic_id:02d}:[\s\S]*?- \*\*Status\*\*:\s*)(?:[⏳❌][^\n]+)', rf'\1✅ COMPLETED', plan_text)
        else:
            pattern = rf'- \[[ xX]\] \*\*Topic (?:T|t)?0*{rep.topic_id}:'
            replacement = f'- [ ] **Topic T{rep.topic_id:02d}:'
            plan_text = re.sub(pattern, replacement, plan_text)

        plan_file.write_text(plan_text, encoding="utf-8")

    def _sync_plan_md(self, reports: List[TopicRunReport]) -> None:
        """
        Synchronizes persistent memory into plan.md (Pillar 8: Persistent Memory in Loop Engineering).
        Marks completed topics with [x], logs QA status, and keeps state across loop iterations.
        """
        plan_file = Path("plan.md")
        if not plan_file.exists():
            plan_file = self.workspace_dir.parent / "plan.md"
        if not plan_file.exists():
            return

        plan_text = plan_file.read_text(encoding="utf-8")
        report_map = {r.topic_id: r for r in reports}

        for topic in self.topics:
            rep = report_map.get(topic.topic_id)
            if rep and rep.status == "APPROVED":
                pattern = rf'- \[[ xX]\] \*\*Topic (?:T|t)?0*{topic.topic_id}:'
                replacement = f'- [x] **Topic {topic.topic_id}:'
                plan_text = re.sub(pattern, replacement, plan_text)
            elif rep and rep.status != "APPROVED":
                pattern = rf'- \[[ xX]\] \*\*Topic (?:T|t)?0*{topic.topic_id}:'
                replacement = f'- [ ] **Topic {topic.topic_id}:'
                plan_text = re.sub(pattern, replacement, plan_text)

        plan_file.write_text(plan_text, encoding="utf-8")
        console.print("[dim][*] ซิงค์สถานะ Persistent Memory ลง plan.md สำเร็จ[/dim]")

    def _print_header(self, topics: List[BlueprintTopic]) -> None:
        info_lines = [
            "[bold white]ระบบวิศวกรรม 2-Agent Closed Loop อัตโนมัติ[/bold white]",
            f"[dim]ไฟล์ Blueprint: {self.blueprint_path.name} | วนรอบแก้ไขสูงสุด: {self.max_iterations} รอบ/หัวข้อ | "
            f"หัวข้อที่รัน: {len(topics)} หัวข้อ ({topics[0].topic_id} -> {topics[-1].topic_id})[/dim]",
        ]

        if isinstance(self.orchestrator_llm, AntigravityCLIProvider):
            master_email = AntigravityCredentialManager.get_profile_email("master") or "Google Account ที่ใช้งานอยู่"
            worker_profile = getattr(self.worker_llm, "profile_name", "worker")
            worker_email = AntigravityCredentialManager.get_profile_email(worker_profile) or f"{master_email} (บัญชีเดียวกัน)"
            master_model = getattr(self.orchestrator_llm, "model", "")
            worker_model = getattr(self.worker_llm, "model", "")
            timeout_val = getattr(self.worker_llm, "timeout", None)
            timeout_desc = "ไม่จำกัดเวลา (Unlimited - รันต่อเนื่องได้ทั้งวัน)" if timeout_val is None else f"{timeout_val} วินาที"
            info_lines.append(
                f"[bold cyan]Agent 1 (หัวหน้า/QA):[/bold cyan] {master_email} [dim]({master_model})[/dim] | "
                f"[bold green]Agent 2 (ช่างเขียนโค้ด):[/bold green] {worker_email} [dim]({worker_model})[/dim]"
            )
            info_lines.append(f"[dim]ระยะเวลาตอบสนอง: [bold green]{timeout_desc}[/bold green][/dim]")

        console.print(Panel(
            "\n".join(info_lines),
            title="[bold cyan]🚀 เริ่มต้นระบบ 2-Agent Closed-Loop[/bold cyan]",
            border_style="cyan",
        ))

    def _print_summary(self, reports: List[TopicRunReport]) -> None:
        table = Table(title="📊 สรุปผลการทำงาน (Closed-Loop Summary)", border_style="cyan")
        table.add_column("รหัสหัวข้อ (ID)", justify="center", style="bold")
        table.add_column("ชื่อหัวข้อ (Title)", style="white")
        table.add_column("สถานะ (Status)", justify="center")
        table.add_column("รอบที่ใช้ (Iterations)", justify="center")
        table.add_column("ไฟล์ที่สร้างขึ้น (Files Created)", style="dim")

        approved_count = 0
        for r in reports:
            if r.status == "APPROVED":
                status_colored = "[bold green]ผ่านแล้ว (APPROVED)[/bold green]"
                approved_count += 1
            else:
                status_colored = "[bold red]ไม่ผ่าน (FAILED)[/bold red]"

            table.add_row(
                str(r.topic_id),
                r.title,
                status_colored,
                str(r.iterations_used),
                ", ".join(r.files_created) if r.files_created else "ไม่มี",
            )

        console.print(table)
        console.print(
            f"\n[bold]{approved_count}/{len(reports)}[/bold] หัวข้อผ่านการอนุมัติเรียบร้อยแล้ว "
            f"ไฟล์ทั้งหมดบันทึกอยู่ที่: [cyan]{self.workspace_dir.resolve()}[/cyan]\n"
        )


def create_topic_from_prompt(
    prompt_text: str,
    llm: BaseLLMProvider,
    existing_topics: List[BlueprintTopic],
    workspace_dir: Path
) -> BlueprintTopic:
    """Takes a natural language task from the user (Thai or English) and uses Agent 1 to convert it into a BlueprintTopic."""
    next_id = max([t.topic_id for t in existing_topics], default=0) + 1
    system_prompt = (
        "You are Agent 1 (Orchestrator & Lead System Architect).\n"
        "Convert the user's task request into a structured JSON topic for our engineering blueprint.\n"
        "Requirements must be clean and actionable. Target files should use appropriate extensions (e.g. src/... html, css, js).\n"
        "Acceptance criteria should specify concrete checks.\n"
        "Test commands should be python one-liners (using pathlib to verify files exist and contain key strings).\n"
        "Output ONLY a valid JSON object matching this schema:\n"
        "{\n"
        f'  "topic_id": {next_id},\n'
        '  "title": "Short title in Thai or English",\n'
        '  "description": "Clear description",\n'
        '  "target_files": ["src/..."],\n'
        '  "requirements": ["Requirement 1", "Requirement 2"],\n'
        '  "acceptance_criteria": ["Criteria 1", "Criteria 2"],\n'
        '  "test_commands": ["python -c \\"import pathlib; assert pathlib.Path(\'output/src/...\').exists()\\""]\n'
        "}"
    )

    console.print(f"[bold cyan][*] Agent 1 กำลังวิเคราะห์และแปลงคำสั่งของคุณเป็น Blueprint Topic {next_id}...[/bold cyan]")
    try:
        raw = llm.generate(system_prompt, f"User Task Request:\n{prompt_text}")
        cleaned = re.search(r"\{.*\}", raw, re.DOTALL)
        if cleaned:
            data = json.loads(cleaned.group(0))
            topic = BlueprintTopic(
                topic_id=int(data.get("topic_id", next_id)),
                title=str(data.get("title", f"Task {next_id}")),
                description=str(data.get("description", prompt_text)),
                target_files=list(data.get("target_files", [f"src/task_{next_id}.html"])),
                requirements=list(data.get("requirements", [prompt_text])),
                acceptance_criteria=list(data.get("acceptance_criteria", ["Target files exist and are valid."])),
                test_commands=list(data.get("test_commands", [])),
            )
            return topic
    except Exception as e:
        console.print(f"[yellow][!] ไม่สามารถแปลงอัตโนมัติได้: {e}. กำลังใช้ค่าเริ่มต้น...[/yellow]")

    sanitized_title = prompt_text[:50].strip()
    return BlueprintTopic(
        topic_id=next_id,
        title=sanitized_title,
        description=prompt_text,
        target_files=[f"src/task_{next_id}.html", f"src/styles/task_{next_id}.css"],
        requirements=[prompt_text, "Clean responsive design", "Accessible semantic markup"],
        acceptance_criteria=["Target files exist on disk."],
        test_commands=[f"python -c \"import pathlib; assert pathlib.Path('output/src/task_{next_id}.html').exists()\""],
    )


